"use client";
import {useState} from "react";
import { ArtemisScope } from "@/components/application/artemis/artemis-scope";
import { ArtemisButton, ArtemisTextField, ArtemisCheckbox, ArtemisSelect, ArtemisAnimatedModal, ArtemisSegmentedTabs, ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "@/components/application/artemis/artemis-foundations";
export default function Demo(_props: { variant?: string }){const[checked,setChecked]=useState(false),[value,setValue]=useState("overview"),[open,setOpen]=useState(false);return <ArtemisScope className="art:w-full art:max-w-lg art:min-w-0 art:rounded-2xl art:bg-background art:p-4 art:text-foreground"><ArtemisMorphicTooltipProvider><div className="art:flex art:min-w-0 art:flex-col art:gap-3"><ArtemisSegmentedTabs listClassName="art:inline-flex art:max-w-full art:self-start art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1" items={[{value:"overview",label:"Overview"},{value:"activity",label:"Activity"}]} value={value} onValueChange={setValue}/><ArtemisTextField label="Project name" placeholder="Untitled project"/><ArtemisSelect ariaLabel="View" value={value} onChange={setValue} options={[{value:"overview",label:"Overview"},{value:"activity",label:"Activity"}]}/><ArtemisCheckbox checked={checked} onCheckedChange={setChecked} label="Enable notifications"/><ArtemisMorphicTooltip content="Open project settings"><ArtemisButton onClick={()=>setOpen(true)}>Open settings</ArtemisButton></ArtemisMorphicTooltip></div><ArtemisAnimatedModal open={open} onClose={()=>setOpen(false)}><div className="art:p-6"><h2 className="art:mb-4 art:text-lg art:font-medium">Project settings</h2><ArtemisButton onClick={()=>setOpen(false)}>Done</ArtemisButton></div></ArtemisAnimatedModal></ArtemisMorphicTooltipProvider></ArtemisScope>}

